    stoi = {ch: i for i, ch in enumerate(vocab)}
    itos = {i: ch for ch, i in stoi.items()}
    def encode(s):
        return [stoi.get(c, 0) for c in s]
    def decode(ids):
        return "".join(itos[i] for i in ids)
    return stoi, itos, encode, decode

